STATION.LRDEF = {
    element:"a file the entity config never claims — it sits in the unclaimed area so you can see what the map is blind to; claim it to move it home",
    route:"a screen you navigate to — where a journey naturally starts",
    component:"a piece of UI that draws something on a screen",
    hook:"reusable logic a component calls — it remembers state for it",
    type:"a shape of data — describes things, never runs",
    store:"frontend state that outlives one screen (a context, a store) — the frontend's table: its fields are its value type's members",
    module:"the leftover shelf — helpers, API calls and feature logic that aren't UI",
    web:"a place in the frontend that calls the API",
    unknown:"\"we could not tell\" — said out loud, instead of calling it a module",
    "mclass:api":"the frontend's phone line to the backend — the fetch calls live here",
    "mclass:render-fn":"draws UI from a plain function — a view without a component name",
    "mclass:model":"the feature's data shapes and mappers — turns API replies into what screens show",
    "mclass:config":"app wiring — clients, config, setup",
    "mclass:lib":"shared plumbing used everywhere — formatting, i18n, assets, design-system helpers",
    "mclass:logic":"the feature's rules and calculations — no UI, no API",
    "hrole:fetcher":"the hook that calls the API — its fetch site is the bridge",
    "hrole:streamer":"the hook whose fetch is a stream — the response keeps arriving",
    "hrole:store":"the hook that reads or writes client state (the writer/reader split waits on setter extraction)",
    "hrole:orchestrator":"composes other hooks — touches no data itself",
    "hrole:effect":"a side channel — analytics, logging, idempotency — no data, no UI",
    "hrole:deriver":"computes from its inputs — no store, no API",
    endpoint:"the API door the frontend knocks on — one URL and a verb",
    "function":"one backend step — the work behind an endpoint",
    schema:"the shape of what an endpoint takes in or hands back",
    model:"a database table — where the data actually lives",
    external:"a table this area points at but doesn't own",
    entity:"a business area — a planet of related screens, endpoints and tables",
    middleware:"a wrapper the app runs on EVERY request before any endpoint is chosen — CORS, rate limit, idempotency; the building's front door, not a journey's gate",
    flag:"a switch that turns a lane on or off — the journey stops here when it is off",
    provider:"an outside service the backend calls — AI, email, payments; where the trace leaves your code",
    prompt:"the text handed to an AI provider — built by a function, sent by a provider call",
    view:"a whole screen — the top-level component a route mounts",
    "feclass:connector":"the component that fetches and wires data into a screen",
    "feclass:container":"arranges its children — the screen's structure",
    "feclass:leaf":"a small widget reused everywhere (a button, a chip)",
    "feclass:private":"used inside one screen only — never shared",
    "feclass:detached":"a component with no drawn renderer — detached from the drawn tree: the app shell, or a piece whose renderer the map cannot see; never a view",
    "method:GET":"reads — asks for data, changes nothing",
    "method:POST":"creates — sends something new to be stored",
    "method:PUT":"replaces — overwrites the whole thing",
    "method:PATCH":"updates — changes some fields",
    "method:DELETE":"removes it",
    "method:BOOT":"runs once when the app starts",
    "method:TASK":"runs on a worker, dispatched by name from a queue",
    "role:accessor":"the function that actually touches the database",
    "role:caller":"coordinates other functions — touches no data itself",
    "role:gate":"the check that can say no — as a guard on the endpoint (its Depends list, on the card) or as a function inside the chain; one act, two doors (D4 2026-09-05)",
    "role:pure":"computes from its inputs — no database, no side effects",
    "count:N":"how many nested shapes are tucked inside this one",
    "x:fk":"one table points at a row in another",
    "x:calls":"one backend function calls another, across areas",
    "delivery:stream":"the answer arrives in pieces while you wait, not all at once at the end",
    "pclass:llm":"a model that writes text for you", "pclass:embed":"turns your text into numbers so it can be compared", "pclass:vector":"where the app keeps meanings so it can search by similarity", "pclass:agent":"the conductor that decides which model call comes next", "pclass:infra":"plumbing the app rents — cache, queue, storage, a platform", "pclass:http":"a plain call out to someone else's URL", "pclass:observability":"where errors go to be seen", "pclass:payments":"where money moves",
    "x:dispatches":"a function hands work to a worker or an event bus by name — it names the job and moves on; the job runs later, somewhere else",
    "x:imports":"one file pulls another in, across areas",
    "x:bridge":"the frontend calling the API",
    "x:rollup":"an endpoint reaching a table through the functions it calls",
    "x:access":"the actual read or write of a table by a function",
    "x:renders":"a component draws another — or a route mounts its view (compiler-proven)",
    "x:uses":"a component or hook calls a hook",
    "x:reads":"a component or hook reads a store — the frontend's table",
    "x:typed":"a piece handles a shape: the type it takes or returns",
    "x:fecall":"a piece calls a plain function in a module (inferred by graft — a floor)",
    "x:Cargo":"data moving between areas — a bigger ship carries a bigger payload",
    "x:Test chip":"a test that crosses areas end to end",
    "x:api":"backend tests (pytest)",
    "x:web":"frontend tests (vitest)",
    "x:e2e":"browser tests (playwright)",
    "x:T1":"too big",
    "x:T2":"much too big",
    "x:T3":"split it now",
    "x:Unguarded":"changed, and no test covers it",
    "x:Blast":"touching this touches a lot — high coupling",
    "x:Flak":"failing or untested while a change is in flight",
    "x:Satellites":"who calls this — its users",
    "x:Star":"used all over the area, but never shown on its own" };
